from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

FILES={'alliance_truth_integrity_v426.py': '', 'alliance_autonomous_student_v435.py': ''}
REG="alliance_optional_property_modules.py"

def chk(p): compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    req=["alliance_autonomous_student_v434.py","alliance_autonomous_student_v433.py","alliance_autonomous_student_v432.py",
         "alliance_autonomous_student_v431.py","alliance_autonomous_student_v430.py","alliance_cre_academy_v402.py",REG]
    miss=[x for x in req if not (r/x).exists()]
    if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))
    v434=(r/"alliance_autonomous_student_v434.py").read_text(encoding="utf-8")
    if 'VERSION = "4.3.4-ALLIANCE-AUTONOMOUS-STUDENT-V5-DEMAND-OWNERSHIP-CLOSURE"' not in v434:
        raise SystemExit("Unexpected 4.3.4 baseline. Refusing install.")
    for name,data in FILES.items():
        (r/name).write_text(base64.b64decode(data).decode(),encoding="utf-8")
        chk(r/name)

    reg=r/REG; old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v435-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"; shutil.copy2(reg,bak)
    marker="# FOUNDATION 4.3.5 - Truth Integrity Repair"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0: raise SystemExit("Registrar return not found.")
        block=r"""
    # FOUNDATION 4.3.5 - Truth Integrity Repair
    try:
        import alliance_truth_integrity_v426 as v426
        result["truth_integrity_v426"] = {**v426.register(core), "error": None}
    except Exception as exc:
        result["truth_integrity_v426"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","fail_safe":True}
    try:
        import alliance_autonomous_student_v435 as v435
        result["autonomous_v435"] = {**v435.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v435"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")
    chk(reg)
    print("Foundation 4.2.6 + 4.3.5 installed")
    print("Pseudo-truth corrections are versioned; original V4 truth untouched")
    print("V5 freeze: 0")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v435")
    print("Backup:",bak)

if __name__=="__main__": main()
